import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ChevronLeft, Camera, ImagePlus, Activity, Edit2, Trash2, Calendar, MapPin, Link, Unlink, ActivityIcon, Plus, CheckCircle, XCircle, Beef, ThermometerSun, Weight, Stethoscope, ChevronRight } from 'lucide-react';
import { useTernakStore } from '../store/useTernakStore';
import useSettingsStore from '@/store/settingsStore';
import { motion } from 'framer-motion';
import translations from '@/lib/i18n';
import CowAnalyticsView from '@/components/shared/CowAnalyticsView';
import CowEstrusView from '@/components/shared/CowEstrusView';
import PairCollarModal from '@/components/shared/PairCollarModal';
import { Stepper, StepperItem, StepperIndicator, StepperTitle, StepperDescription, StepperSeparator } from "../components/ui/stepper";

const hitungUsia = (lahir, lang) => {
  if(!lahir) return '';
  const today = new Date();
  let birthDate;
  if (typeof lahir === 'string' && lahir.includes('/')) {
    const parts = lahir.split('/');
    if (parts.length === 3) {
      birthDate = new Date(parseInt(parts[2]), parseInt(parts[1]) - 1, parseInt(parts[0]));
    } else {
      birthDate = new Date(lahir);
    }
  } else {
    birthDate = new Date(lahir);
  }

  if (isNaN(birthDate.getTime())) return '';

  let years = today.getFullYear() - birthDate.getFullYear();
  let months = today.getMonth() - birthDate.getMonth();
  if (months < 0 || (months === 0 && today.getDate() < birthDate.getDate())) {
    years--;
    months += 12;
  }
  if (lang === 'id') {
    return years > 0 ? `${years} tahun ${months} bulan` : `${months} bulan`;
  } else {
    return years > 0 ? `${years} years ${months} months` : `${months} months`;
  }
};

export default function DetailTernak() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { fetchSapiDetail, selectedSapi, loading } = useTernakStore();
  const { language } = useSettingsStore();
  const lang = language || 'id';
  const t = translations[lang];

  const [activeTab, setActiveTab] = useState('riwayat');
  const [isPairModalOpen, setIsPairModalOpen] = useState(false);
  const [pairSelectedSapi, setPairSelectedSapi] = useState(null);
  const [pairSelectedCollar, setPairSelectedCollar] = useState(null);

  useEffect(() => {
    if (id) {
      fetchSapiDetail(id);
    }
  }, [id, fetchSapiDetail]);

  const sortedReproHistory = useMemo(() => {
    if (!selectedSapi || !selectedSapi.reproduksi) return [];
    return [...selectedSapi.reproduksi].sort((a, b) => {
      const dateA = new Date(a.tanggal_ib || a.service_date).getTime();
      const dateB = new Date(b.tanggal_ib || b.service_date).getTime();
      return dateB - dateA;
    });
  }, [selectedSapi]);

  if (loading || !selectedSapi) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center h-screen bg-[#F3F4F6]">
        <div className="w-10 h-10 border-4 border-[#2E7D32] border-t-transparent rounded-full animate-spin"></div>
        <p className="mt-4 text-gray-500 font-medium">Memuat data ternak...</p>
      </div>
    );
  }

  const usiaText = hitungUsia(selectedSapi.bulan_tahun_lahir, lang);
  const isPregnant = selectedSapi.status_kebuntingan === 'Bunting' || selectedSapi.status_kebuntingan?.toLowerCase().includes('pregnant');

  return (
    <div className="min-h-screen bg-[#F4F5F7] pb-24 lg:pb-8 flex flex-col">
      {/* ── HEADER NAVIGATION ── */}
      <div className="bg-white px-6 py-4 flex items-center gap-4 sticky top-0 z-50 border-b border-gray-100 shadow-sm">
        <button onClick={() => navigate('/ternak')} className="p-2 hover:bg-gray-100 rounded-full transition-colors group">
          <ChevronLeft size={24} className="text-gray-500 group-hover:text-gray-900" />
        </button>
        <div>
          <h1 className="text-xl font-bold text-gray-900">{selectedSapi.nama || 'Detail Ternak'}</h1>
          <p className="text-xs text-gray-500 font-medium tracking-wide">ID: {selectedSapi.id}</p>
        </div>
        <div className="ml-auto flex items-center gap-2">
          <button className="p-2 bg-gray-50 text-gray-600 rounded-xl hover:bg-gray-100 transition-colors border border-gray-200">
            <Edit2 size={18} />
          </button>
          <button className="p-2 bg-red-50 text-red-600 rounded-xl hover:bg-red-100 transition-colors border border-red-100">
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      {/* ── MAIN CONTENT (Profile Sidebar Layout) ── */}
      <div className="flex-1 p-6 max-w-[1400px] mx-auto w-full flex flex-col lg:flex-row gap-6">

        {/* LEFT COLUMN: Profile Card (30%) */}
        <div className="w-full lg:w-[320px] shrink-0 flex flex-col gap-6">
          <div className="bg-white rounded-[24px] p-6 shadow-sm border border-gray-100 flex flex-col items-center relative overflow-hidden">
            {/* Top decorative gradient */}
            <div className="absolute top-0 left-0 right-0 h-24 bg-gradient-to-b from-gray-50 to-white" />

            {/* Avatar */}
            <div className="w-28 h-28 rounded-full bg-gray-100 overflow-hidden shrink-0 border-4 border-white shadow-md relative group mt-4 z-10">
              {selectedSapi.foto ? (
                <img src={selectedSapi.foto} alt={selectedSapi.nama} className="w-full h-full object-cover" />
              ) : (
                <div className="w-full h-full flex items-center justify-center bg-gray-50">
                  <Beef size={40} className="text-gray-300" />
                </div>
              )}
              <label className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center cursor-pointer">
                <Camera size={24} className="text-white" />
                <input type="file" accept="image/*" className="hidden" />
              </label>
            </div>

            {/* Name & ID */}
            <div className="text-center mt-4 mb-5 z-10">
              <h2 className="text-2xl font-extrabold text-gray-900 tracking-tight">{selectedSapi.nama || '--'}</h2>
              <p className="text-sm font-medium text-gray-500 mt-0.5">ID: {selectedSapi.id}</p>
            </div>

            {/* Badges */}
            <div className="flex flex-col gap-2 w-full z-10 mb-6">
              <div className="px-4 py-2 bg-[#E8F5E9] text-[#2E7D32] rounded-full text-[13px] font-bold border border-[#C8E6C9] flex items-center justify-center gap-2">
                <div className="w-2 h-2 rounded-full bg-[#4CAF50]" /> {selectedSapi.status_kesehatan || 'Sehat / Aktif'}
              </div>
              <div className={`px-4 py-2 rounded-full text-[13px] font-bold border flex items-center justify-center gap-2 ${isPregnant ? 'bg-amber-50 text-amber-700 border-amber-200' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>
                {isPregnant ? 'Bunting' : 'Tidak Bunting'}
              </div>
              <div className="px-4 py-2 bg-blue-50 text-blue-700 rounded-full text-[13px] font-bold border border-blue-100 flex items-center justify-center gap-2">
                Fase: {selectedSapi.fase_produksi || 'Laktasi'}
              </div>
            </div>

            <div className="w-full h-px bg-gray-100 mb-6" />

            {/* Vertical Quick Stats */}
            <div className="w-full flex flex-col gap-4 mb-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3 text-gray-500">
                  <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center"><Weight size={16} /></div>
                  <span className="text-sm font-medium">Berat</span>
                </div>
                <span className="font-bold text-gray-900">{selectedSapi.berat_estimasi || '--'} kg</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3 text-gray-500">
                  <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center"><ThermometerSun size={16} /></div>
                  <span className="text-sm font-medium">Suhu</span>
                </div>
                <span className="font-bold text-gray-900">{selectedSapi.suhu || '--'} °C</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3 text-gray-500">
                  <div className="w-8 h-8 rounded-full bg-gray-50 flex items-center justify-center"><Stethoscope size={16} /></div>
                  <span className="text-sm font-medium">Total IB</span>
                </div>
                <span className="font-bold text-gray-900">{sortedReproHistory.length} kali</span>
              </div>
            </div>

            {/* Smart Collar Status Box */}
            <div className="w-full mt-auto">
              {selectedSapi.collar_id ? (
                <div className="bg-[#2E7D32] rounded-[16px] p-4 text-white flex items-center gap-3 shadow-sm relative overflow-hidden group">
                  <div className="absolute right-0 top-0 h-full w-24 bg-white/10 skew-x-12 translate-x-10 group-hover:translate-x-4 transition-transform" />
                  <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center shrink-0">
                    <ActivityIcon size={20} className="text-white animate-pulse" />
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-bold leading-tight">Collar Aktif</p>
                    <p className="text-[11px] text-white/80 font-medium mt-0.5">Pemantauan 24/7</p>
                  </div>
                  <button 
                    onClick={() => { setPairSelectedSapi(selectedSapi); setIsPairModalOpen(true); }}
                    className="p-2 bg-white/10 hover:bg-white/20 rounded-lg transition-colors relative z-10"
                    title="Lepas Collar"
                  >
                    <Unlink size={14} className="text-white" />
                  </button>
                </div>
              ) : (
                <div className="bg-gray-50 rounded-[16px] p-4 border border-gray-200 border-dashed text-center flex flex-col items-center gap-2">
                  <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center">
                    <ActivityIcon size={18} className="text-gray-400" />
                  </div>
                  <p className="text-xs text-gray-500 font-medium">Belum ada collar terpasang</p>
                  <button 
                    onClick={() => { setPairSelectedSapi(selectedSapi); setIsPairModalOpen(true); }}
                    className="mt-1 w-full py-2 bg-white border border-gray-200 text-gray-700 text-sm font-bold rounded-xl hover:bg-gray-50 hover:border-gray-300 transition-colors"
                  >
                    Pasang Collar
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* RIGHT COLUMN: Workspace Area (70%) */}
        <div className="flex-1 flex flex-col min-w-0">

          {/* Sleek Tab Bar */}
          <div className="bg-white rounded-t-[24px] border-b border-gray-100 shadow-sm flex overflow-x-auto no-scrollbar px-2">
            {['riwayat', 'estrus', 'linimasa', 'analitik'].map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-6 py-5 text-[15px] font-bold whitespace-nowrap transition-colors relative ${
                  activeTab === tab ? 'text-[#2E7D32]' : 'text-gray-500 hover:text-gray-800'
                }`}
              >
                {tab === 'riwayat' && 'Riwayat Reproduksi'}
                {tab === 'estrus' && 'Deteksi Estrus'}
                {tab === 'linimasa' && 'Linimasa'}
                {tab === 'analitik' && 'Analitik & Grafik'}

                {activeTab === tab && (
                  <motion.div layoutId="detailTabIndicator" className="absolute bottom-0 left-4 right-4 h-[3px] bg-[#2E7D32] rounded-t-full" />
                )}
              </button>
            ))}
          </div>

          {/* Tab Content Canvas */}
          <div className="bg-white rounded-b-[24px] shadow-sm p-6 min-h-[500px]">
            {activeTab === 'riwayat' && (
              <div className="flex flex-col gap-6 animate-in fade-in duration-300">
                <div className="flex justify-between items-center">
                   <h3 className="text-lg font-bold text-gray-900">Catatan Reproduksi</h3>
                   <button className="text-sm font-bold bg-[#2E7D32] text-white px-5 py-2.5 rounded-xl flex items-center gap-2 hover:bg-[#1B5E20] transition-colors shadow-sm">
                     <Plus size={16} /> Catat Inseminasi
                   </button>
                </div>

                {/* Modern Table for History */}
                <div className="overflow-x-auto rounded-2xl border border-gray-100">
                  <table className="w-full text-left border-collapse">
                    <thead>
                      <tr className="bg-gray-50 border-b border-gray-100">
                        <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-wider">Event</th>
                        <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-wider">Tanggal</th>
                        <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-wider">Metode</th>
                        <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-wider">Inseminator</th>
                        <th className="px-4 py-3 text-xs font-bold text-gray-500 uppercase tracking-wider text-right">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                      {sortedReproHistory.length > 0 ? (
                        sortedReproHistory.map((item, idx) => (
                          <tr key={idx} className="hover:bg-gray-50 transition-colors">
                            <td className="px-4 py-4">
                              <p className="font-bold text-gray-900 text-sm">IB Ke-{item.jumlah_ib || idx + 1}</p>
                            </td>
                            <td className="px-4 py-4 text-sm text-gray-600">
                              {item.tanggal_ib || item.service_date || '-'}
                            </td>
                            <td className="px-4 py-4 text-sm text-gray-600">
                              {item.metode ? item.metode.toUpperCase() : '-'}
                            </td>
                            <td className="px-4 py-4 text-sm text-gray-600">
                              {item.pemberi_ib || '-'}
                            </td>
                            <td className="px-4 py-4 text-right">
                              <span className={`inline-flex px-2.5 py-1 rounded-md text-[11px] font-bold uppercase tracking-wider ${item.results === true || item.results === 'true' ? 'bg-green-50 text-green-700 border border-green-100' : item.results === false || item.results === 'failed' ? 'bg-red-50 text-red-700 border border-red-100' : 'bg-gray-100 text-gray-600 border border-gray-200'}`}>
                                {item.results === true || item.results === 'true' ? 'Bunting' : item.results === false || item.results === 'failed' ? 'Gagal' : 'Menunggu'}
                              </span>
                            </td>
                          </tr>
                        ))
                      ) : (
                        <tr>
                          <td colSpan="5" className="px-4 py-12 text-center text-gray-400 text-sm font-medium">Belum ada riwayat reproduksi tercatat.</td>
                        </tr>
                      )}
                    </tbody>
                  </table>
                </div>
              </div>
            )}

            {activeTab === 'estrus' && (
              <div className="animate-in fade-in duration-300">
                <CowEstrusView selectedCow={selectedSapi} reproHistory={sortedReproHistory} />
              </div>
            )}

            {activeTab === 'linimasa' && (
               <div className="animate-in fade-in duration-300">
                 <h3 className="text-lg font-bold text-gray-900 mb-6">Linimasa Aktivitas</h3>
                 <Stepper orientation="vertical" defaultValue={2} className="w-full">
                   <div className="flex flex-col gap-6 relative before:absolute before:inset-0 before:ml-[17px] before:-translate-x-px before:w-0.5 before:bg-gray-100">
                      <div className="text-center text-sm text-gray-400 py-12 border-2 border-dashed border-gray-100 rounded-2xl">
                        Tidak ada aktivitas terbaru di linimasa.
                      </div>
                   </div>
                 </Stepper>
               </div>
            )}

            {activeTab === 'analitik' && (
               <div className="animate-in fade-in duration-300">
                 <CowAnalyticsView selectedCow={selectedSapi} />
               </div>
            )}
          </div>
        </div>
      </div>

      <PairCollarModal
        isOpen={isPairModalOpen}
        onClose={() => { setPairSelectedSapi(null); setPairSelectedCollar(null); setIsPairModalOpen(false); }}
        pairSelectedSapi={pairSelectedSapi}
        setPairSelectedSapi={setPairSelectedSapi}
        pairSelectedCollar={pairSelectedCollar}
        setPairSelectedCollar={setPairSelectedCollar}
      />
    </div>
  );
}
